using System;using System.Drawing;using System.Reflection;using System.Windows.Forms;using IslandIntegrated;
class Tests {
 [STAThread] static int Main(string[] args){var now=DateTimeOffset.UtcNow;var x=new AutoloopSnapshot{State="connected",ObservedAt=now,QuestionId="1",QuestionText="请选择下一步",TaskTitle="演示任务",CardFingerprint="test",Options=new[]{new AutoloopOption{Id="0",Label="继续"}}};
 Check(AutoloopSidebarControl.IsFresh(x,now),"fresh");x.ObservedAt=now.AddSeconds(-30);Check(AutoloopSidebarControl.IsFresh(x,now),"30s boundary");x.ObservedAt=now.AddSeconds(-31);Check(!AutoloopSidebarControl.IsFresh(x,now),"expired");x.ObservedAt=now.AddSeconds(6);Check(!AutoloopSidebarControl.IsFresh(x,now),"future");x.ObservedAt=null;Check(!AutoloopSidebarControl.IsFresh(x,now),"missing time");x.ObservedAt=now; x.State="offline";Check(!AutoloopSidebarControl.IsFresh(x,now),"offline");x.State="connected";
 using(var c=new AutoloopSidebarControl()){var can=typeof(AutoloopSidebarControl).GetMethod("CanAnswer",BindingFlags.NonPublic|BindingFlags.Instance);c.Size=new Size(160,160);c.Present(x,false,null);Check((bool)can.Invoke(c,null),"fresh option allowed");using(var b=new Bitmap(c.Width,c.Height)){c.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(System.IO.Path.Combine(args[0],"autoloop-fresh-fixture.png"));}x.ObservedAt=now.AddSeconds(-31);c.Present(x,false,null);Check(!(bool)can.Invoke(c,null),"expired disabled");Check(c.AccessibleName.Contains("过期"),"expired status");using(var b=new Bitmap(c.Width,c.Height)){c.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(System.IO.Path.Combine(args[0],"autoloop-expired-fixture.png"));}x.ObservedAt=now;c.Present(x,true,null);Check(!(bool)can.Invoke(c,null),"pending disabled");}
 Console.WriteLine("Freshness and answer gating: 10 passed");return 0;}
 static void Check(bool x,string m){if(!x)throw new Exception(m);}
}
